package ru.ileech.ndicamera;
import android.app.*;
import android.os.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;

public class SettingsActivity extends Activity {
 private TextView status;private EditText name;private final Handler handler=new Handler();private final Runnable refresh=new Runnable(){public void run(){status.setText(Updates.status);Updates.offer(SettingsActivity.this);handler.postDelayed(this,1000);}};
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextColor(Color.WHITE);v.setTextSize(size);v.setPadding(0,dp(12),0,dp(12));return v;}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xff0f172a);getWindow().setNavigationBarColor(0xff0f172a);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff0f172a);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(24),dp(24),dp(30));scroll.addView(root);setContentView(scroll);TextView back=text("‹  Настройки NDI Camera",23);back.setOnClickListener(v->finish());root.addView(back);root.addView(text("Название устройства",14));name=new EditText(this);name.setSingleLine();name.setTextColor(-1);name.setText(Updates.prefs(this).getString("deviceName",Build.MODEL+" Camera"));root.addView(name);toggle(root,"Показывать битрейт","showBitrate",true);toggle(root,"Автообновление · каждые 24 часа","autoUpdate",true);root.addView(text("Обновления загружаются из Mike-iLeech/NDICamera Releases. Перед установкой проверяются SHA-256, пакет, версия и подпись. Установку подтверждает Android.",14));Button check=new Button(this);check.setText("Проверить обновления");root.addView(check);check.setOnClickListener(v->Updates.check(this,true,null));status=text(Updates.status,14);root.addView(status);root.addView(text("Версия 0.1.1 · Android Camera2\nNDI® · ndi.video",13));Button licenses=new Button(this);licenses.setText("Лицензии NDI");root.addView(licenses);licenses.setOnClickListener(v->{try{java.io.InputStream in=getAssets().open("NDI-License.txt");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();TextView content=text(out.toString("UTF-8"),12);ScrollView box=new ScrollView(this);box.addView(content);new AlertDialog.Builder(this).setTitle("NDI SDK License").setView(box).setPositiveButton("Закрыть",null).show();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}});}
 private void toggle(LinearLayout root,String title,String key,boolean fallback){Switch control=new Switch(this);control.setText(title);control.setTextColor(-1);control.setPadding(0,dp(18),0,dp(18));control.setChecked(Updates.prefs(this).getBoolean(key,fallback));root.addView(control);control.setOnCheckedChangeListener((v,on)->{Updates.prefs(this).edit().putBoolean(key,on).apply();if(key.equals("autoUpdate")){Updates.schedule(this);if(on)Updates.check(this,false,null);}});}
 @Override public void finish(){if(name!=null&&name.getText().toString().trim().isEmpty()){name.setError("Введите имя источника");return;}save();super.finish();}
 private void save(){if(name!=null&&!name.getText().toString().trim().isEmpty())Updates.prefs(this).edit().putString("deviceName",name.getText().toString().trim()).apply();}
 @Override protected void onResume(){super.onResume();handler.post(refresh);}
 @Override protected void onPause(){save();handler.removeCallbacks(refresh);super.onPause();}
}
